mapper.select:
SELECT authority_id AS authorityId, authority_code AS authorityCode, authority_nm AS authorityNm, authority_dc AS authorityDc, authority_level AS authorityLevel, tenant_scoped AS tenantScoped, use_at AS useAt, created_at AS frstRegistPnttm, 'SYSTEM' AS frstRegisterId, updated_at AS lastUpdtPnttm, 'SYSTEM' AS lastUpdusrId FROM tb_authority WHERE 1=1
AND use_at = #{useAt}
AND authority_code ILIKE '%' || #{searchKeyword} || '%'
AND authority_nm ILIKE '%' || #{searchKeyword} || '%'
AND authority_dc ILIKE '%' || #{searchKeyword} || '%'
ORDER BY authority_level, authority_code OFFSET #{firstIndex} LIMIT #{recordCountPerPage}

WITH RECURSIVE menu_tree AS ( SELECT m.menu_id, m.menu_code, m.parent_menu_id, m.menu_nm, m.menu_ordr, lpad(coalesce(m.menu_ordr, 0)::text, 5, '0') AS sort_path, 1 AS depth FROM tb_menu m WHERE m.parent_menu_id IS NULL UNION ALL SELECT c.menu_id, c.menu_code, c.parent_menu_id, c.menu_nm, c.menu_ordr, mt.sort_path || '-' || lpad(coalesce(c.menu_ordr, 0)::text, 5, '0') AS sort_path, mt.depth + 1 FROM tb_menu c INNER JOIN menu_tree mt ON c.parent_menu_id = mt.menu_id ) SELECT rmp.rmp_id AS roleMenuPermissionId, rmp.authority_id AS authorityId, a.authority_code AS authorityCode, rmp.menu_id AS menuId, m.menu_code AS menuCode, rmp.permission_id AS permissionId, p.permission_code AS permissionCode, rmp.use_at AS useAt, rmp.crt_dt AS frstRegistPnttm, rmp.crt_id AS frstRegisterId, rmp.upd_dt AS lastUpdtPnttm, rmp.upd_id AS lastUpdusrId, a.authority_nm AS authorityNm, mt.menu_nm AS menuNm, m.menu_url AS menuUrl, p.permission_nm AS permissionNm, p.permission_level AS permissionLevel FROM tb_role_menu_permission rmp LEFT JOIN tb_authority a ON rmp.authority_id = a.authority_id LEFT JOIN menu_tree mt ON rmp.menu_id = mt.menu_id LEFT JOIN tb_menu m ON rmp.menu_id = m.menu_id LEFT JOIN tb_permission p ON rmp.permission_id = p.permission_id WHERE rmp.use_at = 'Y'
AND a.authority_code = #{authorityCode}
AND m.menu_code = #{menuCode}
AND p.permission_code = #{permissionCode}
ORDER BY mt.sort_path

mapper.delete:
DELETE FROM tb_role_menu_permission
WHERE authority_id = (
    SELECT authority_id
    FROM tb_authority
    WHERE authority_code = #{value}
)
